def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a, b, e, i - 1))

    # If m == n-1, all edges are in MST, no output needed
    if m == n - 1:
        return ''

    # Sort edges by weight for Kruskal's algorithm
    sorted_edges = sorted(edges, key=lambda x: x[2])

    # Union-Find for MST
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False

    mst_adj = [[] for _ in range(n + 1)]
    mst_indices = set()

    # Build MST
    for a, b, e, idx in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_indices.add(idx)

    # Binary lifting for path maximum queries
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_w = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)

    # DFS to build tree structure (n=1 case handled)
    if n > 0:
        visited = [False] * (n + 1)

        def dfs(u, p, w, d):
            visited[u] = True
            depth[u] = d
            up[0][u] = p
            max_w[0][u] = w

            for v, weight in mst_adj[u]:
                if not visited[v]:
                    dfs(v, u, max(w, weight), d + 1)

        # Handle n=1 case (no edges possible, but let's be safe)
        if n > 0:
            dfs(1, 1, 0, 0)

    # Build binary lifting tables
    for i in range(1, LOG):
        for u in range(1, n + 1):
            up[i][u] = up[i-1][up[i-1][u]]
            max_w[i][u] = max(max_w[i-1][u], max_w[i-1][up[i-1][u]])

    # Query function for path maximum between two nodes
    def query_path_max(u, v):
        res = 0
        if depth[u] < depth[v]:
            u, v = v, u

        # Bring u to same depth as v
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                res = max(res, max_w[i][u])
                u = up[i][u]

        # Move up together to LCA
        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                res = max(res, max_w[i][u])
                res = max(res, max_w[i][v])
                u = up[i][u]
                v = up[i][v]

        # One more step to reach LCA
        res = max(res, max_w[0][u], max_w[0][v])
        return res

    # Process edges in original input order
    results = []
    for a, b, e, idx in edges:
        if idx not in mst_indices:
            results.append(query_path_max(a, b))

    return '\n'.join(map(str, results))

