def grundy(n, k):
    if n == 0:
        return 0

    # Option 1: remove one cow
    reachable = {grundy(n - 1, k)}

    # Option 2: if n is even, split into k piles of size n/2
    if n % 2 == 0:
        x = n // 2
        if k % 2 == 1:
            # k is odd: XOR of k copies of grundy(x) is grundy(x)
            reachable.add(grundy(x, k))
        else:
            # k is even: XOR of k copies is 0
            reachable.add(0)

    # mex: smallest non-negative integer not in reachable
    mex = 0
    while mex in reachable:
        mex += 1
    return mex

