        for _ in range(n):
            row = list(map(int, lines[line_idx].split()))
            matrix.append(row)
            line_idx += 1

        operations = lines[line_idx]
        line_idx += 1

        # Process each operation
        for op in operations:
            if op == 'R':
                # Shift columns right (column j moves to j+1, wrap around)
                for r in range(n):
                    for c in range(n):
                        new_c = (c + 1) if c < n - 1 else 0
                        matrix[r][new_c] = matrix[r][c]

            elif op == 'L':
                # Shift columns left (column j moves to j-1, wrap around)
                for r in range(n):
                    for c in range(n):
                        new_c = c - 1 if c > 0 else n - 1
                        matrix[r][new_c] = matrix[r][c]

            elif op == 'D':
                # Shift rows down (row i moves to i+1, wrap around)
                for c in range(n):
                    for r in range(n):
                        new_r = r + 1 if r < n - 1 else 0
                        matrix[new_r][c] = matrix[r][c]

            elif op == 'U':
                # Shift rows up (row i moves to i-1, wrap around)
                for c in range(n):
                    for r in range(n):
                        new_r = r - 1 if r > 0 else n - 1
                        matrix[new_r][c] = matrix[r][c]

            elif op == 'I':
                # Invert each row permutation
                for r in range(n):
                    # For each row, find inverse: if row has value p[c]=v, 
