    col_cov = [get_coverage(j, m) for j in range(1, m + 1)]

    # Generate all cell coverage values efficiently
    coverage_vals = []
    for rc in row_cov:
        for cc in col_cov:
            coverage_vals.append(rc * cc)

    # Get the k largest coverage values
    coverage_vals.sort(reverse=True)
    total_score = sum(coverage_vals[:k])

    return str(total_score / total_positions)

