def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    roads = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        a, b = map(int, parts)
        roads.append((a, b))

    # Check if two roads cross
    def crosses(r1, r2):
        a1, b1 = r1
        a2, b2 = r2

        # Normalize so that first endpoint < second endpoint
        if a1 > b1:
            a1, b1 = b1, a1
        if a2 > b2:
            a2, b2 = b2, a2

        # They share an endpoint - no crossing
        if a1 == a2 or a1 == b2 or b1 == a2 or b1 == b2:
            return False

        # Count how many endpoints of r2 fall strictly between endpoints of r1
        in_count = 0
        if a2 > a1 and a2 < b1:
            in_count += 1
        if b2 > a1 and b2 < b1:
            in_count += 1

        # They cross if exactly one endpoint of r2 is between endpoints of r1
        return in_count == 1

    # Build intersection graph: edges represent crossing pairs
    adj = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if crosses(roads[i], roads[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check if graph is bipartite (2-colorable)
    color = [0] * m  # 0=unvisited, 1=inside, 2=outside
    possible = True

    for i in range(m):
        if color[i] == 0:
            color[i] = 1
            stack = [i]
            while stack and possible:
                node = stack.pop()
                node_color = color[node]
                for neighbor in adj[node]:
                    if color[neighbor] == 0:
                        color[neighbor] = 3 - node_color
                        stack.append(neighbor)
                    elif color[neighbor] == node_color:
                        possible = False
                        break

    if not possible:
        return "Impossible"

    # Create result string based on colors
    result = ''.join('i' if c == 1 else 'o' for c in color)
    return result

