    n, k = int(first_line[0]), int(first_line[1])

    phone_numbers = []
    base_cost = 0

    for line in lines[1:2+n]:
        parts = line.split()
        s = parts[0]
        m = int(parts[1])
        phone_numbers.append((s, m))
        base_cost += len(s) * m

    # Get all unique prefixes from all phone numbers
    all_prefixes = set()
    for s, freq in phone_numbers:
        for i in range(1, len(s) + 1):
            all_prefixes.add(s[:i])

    assigned_prefixes = set()
    total_savings = 0

    # Greedy: assign k best prefixes
    for _ in range(k):
        best_gain = 0
        best_prefix = ""

        for p in all_prefixes:
            if p in assigned_prefixes:
                continue

            # Calculate marginal gain of assigning this prefix
            gain = 0
            for s, freq in phone_numbers:
                if s.startswith(p):
                    # Find the length of best matching prefix already assigned
                    best_match_len = 0
                    for ap in assigned_prefixes:
                        if s.startswith(ap):
                            best_match_len = max(best_match_len, len(ap))

                    # If this prefix gives better saving
                    if len(p) > best_match_len:
                        gain += (len(p) - best_match_len) * freq

            # Pick prefix with maximum gain
            if gain > best_gain and gain > 0:
                best_gain = gain
                best_prefix = p

        if best_gain > 0:
            total_savings += best_gain
            assigned_prefixes.add(best_prefix)
        else:
            break

