def solution(input_str):
    """
    Simulates the frog game and returns which frogs survive.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    frogs = []
    for i in range(n):
        p, a = map(int, lines[i + 1].split())
        frogs.append({
            'id': i + 1,
            'pos': p,
            'jump': a,
            'alive': True
        })

    # Map position to list of frog IDs at that position
    pos_to_frogs = {}
    for f in frogs:
        if f['alive']:
            if f['pos'] not in pos_to_frog:
                pos_to_frog[f['pos']] = []
            elif f['id'] not in pos_to_frog[f['pos']]:
                pos_to_frog[f['pos']].append(f['id'])

    def clear_from_pos(pos):
        """Remove a frog from a position's tracking"""
        if pos in pos_to_frog:
            if f['id'] in pos_to_frog[pos]:
                pos_to_frog[pos].remove(f['id'])
                if not pos_to_frog[pos]:
                    del pos_to_frog[pos]

    def frogs_at_pos(pos):
        """Get list of frogs at a position (alive only)"""
        if pos not in pos_to_frog:
            return []
        return [f for f in pos_to_frog[pos] if any(f['alive'] for _ in range(1)) or 
                any(fr['id'] == f for fr in pos_to_frog[pos])]

    turn = 1
    max_iters = n * 2000  # Safety limit

    for iteration in range(max_iters):
        # Check if any frogs are still alive
        if not any(f['alive'] for f in frogs):
            break

        # Get current frog
        current_frog = frogs[(turn - 1) % n]
        turn += 1
        if turn > n:
            turn = 1

        # Still check if frog ID exists
        if (current_frog := frogs[(turn - 1) % n])['alive']:
            if current_frog['jump'] <= 0:
                current_frog['alive'] = False
            else:
                # Jump to new position
                old_pos = current_frog['pos']
                new_pos = (old_pos + current_frog['jump'] - 1) % m + 1
                current_frog['pos'] = new_pos
                current_frog['jump'] -= 1

            # Update position mapping
            if old_pos in pos_to_frogs:
                if current_frog['id'] in pos_to_frogs[old_pos]:
                    pos_to_frogs[old_pos].remove(current_frog['id'])
                    if not pos_to_frogs[old_pos]:
                        del pos_to_frogs[old_pos]

            if new_pos not in pos_to_frogs:
                pos_to_frogs[new_pos] = [current_frog['id']]
            elif current_frog['id'] not in pos_to_frogs[new_pos]:
                pos_to_frogs[new_pos].append(current_frog['id'])

    # Collect surviving frogs
    old_ids = sorted([f['id'] for f in frogs if f['alive']])
    return f"{len(old_ids)}\n{' '.join(map(str, old_ids))}"
